0442\u0430 \u0435\u0441\u0442\u044c \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 (unit representation); \u043d\u0430 \u0434\u0435\u043a\u043e\u0434\u0438\u043d\u0433\u0435 \u0437\u0430\u043f\u0440\u043e\u0441 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043f\u043e \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f\u043c \u044e\u043d\u0438\u0442\u043e\u0432 (\u0434\u0435\u0448\u0451\u0432\u044b\u0439 lookup), \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442 top-k \u044e\u043d\u0438\u0442\u043e\u0432 \u0438 \u0437\u0430\u0442\u0435\u043c attends \u0438\u0445 \u0442\u043e\u043a\u0435\u043d\u0430\u043c \u043f\u043b\u044e\u0441 \u043d\u0435\u0434\u0430\u0432\u043d\u0435\u043c\u0443 \u043e\u043a\u043d\u0443. \u0422.\u0435. \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u0442\u043e\u0433\u043e, \u0447\u0442\u043e \u043c\u043e\u0434\u0435\u043b\u044c \u00ab\u0443\u0432\u0438\u0434\u0438\u0442\u00bb \u0438\u0437 \u0443\u0434\u0430\u043b\u0451\u043d\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430, \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u0434\u0432\u0443\u043c\u044f \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u043c\u0438 inference-time \u0440\u0443\u0447\u043a\u0430\u043c\u0438: (A) **\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u043e\u043c \u0432\u044b\u0431\u043e\u0440\u0430** \u044e\u043d\u0438\u0442\u043e\u0432 (\u0434\u0438\u043d\u0430\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0439 lookup \u043f\u043e \u0437\u0430\u043f\u0440\u043e\u0441\u0443) \u0438 (B) **\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e\u043c \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f**, \u043a\u043e\u0442\u043e\u0440\u044b\u043c \u044d\u0442\u043e\u0442 \u0432\u044b\u0431\u043e\u0440 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f. \u041e\u0431\u0430 \u0444\u0430\u043a\u0442\u043e\u0440\u0430 \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f \u2014 \u044d\u0442\u043e \u0447\u0438\u0441\u0442\u044b\u0439 \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441, \u0447\u0442\u043e \u0438 \u0434\u0435\u043b\u0430\u0435\u0442 \u0444\u0430\u043a\u0442\u043e\u0440\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d \u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c: \u043a\u0430\u0436\u0434\u0430\u044f \u044f\u0447\u0435\u0439\u043a\u0430 = \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 forward-\u043f\u0440\u043e\u0433\u043e\u043d \u043f\u043e\u0432\u0435\u0440\u0445 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e backbone.\n\n**\u0413\u0438\u043f\u043e\u0442\u0435\u0437\u044b (H1\u2013H4):**\n- **H1 (\u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c lookup):** \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0430\u0445, \u0433\u0434\u0435 \u0438\u0441\u043a\u043e\u043c\u0430\u044f \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f \u0432 \u0443\u0434\u0430\u043b\u0451\u043d\u043d\u043e\u0439 \u0447\u0430\u0441\u0442\u0438 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430 (early/mid \u0438\u0433\u043b\u044b, remote-memory LongBench-\u043f\u0443\u043d\u043a\u0442\u044b), \u0437\u0430\u043c\u0435\u043d\u0430 dynamic\u2192random (\u0440\u0430\u0432\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442) \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u0440\u043e\u043d\u044f\u0435\u0442 \u0441\u043a\u043e\u0440; \u043d\u0430 local-\u043f\u0443\u043d\u043a\u0442\u0430\u0445 (late-\u0438\u0433\u043b\u044b, \u043f\u043e\u043f\u0430\u0434\u0430\u044e\u0442 \u0432 \u043e\u043a\u043d\u043e) \u044d\u0444\u0444\u0435\u043a\u0442 \u2248 0. \u042d\u0442\u043e \u0434\u0430\u0451\u0442 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044e \u00ab\u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e \u0440\u043e\u0432\u043d\u043e \u043d\u0430\u0441\u0442\u043e\u043b\u044c\u043a\u043e, \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0437\u0430\u0434\u0430\u0447\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0443\u0434\u0430\u043b\u0451\u043d\u043d\u043e\u0439 \u043f\u0430\u043c\u044f\u0442\u0438\u00bb.\n- **H2 (\u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f):** \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u0441\u043a\u043e\u0440 \u0447\u0435\u0440\u0435\u0437 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u0432\u044b\u0431\u043e\u0440\u0430 (hit-rate) \u0438 \u043f\u0440\u043e\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u0440\u0438 *\u0434\u0438\u043d\u0430\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u043c* lookup; \u044d\u0444\u0444\u0435\u043a\u0442 B \u043c\u0435\u043d\u044c\u0448\u0435 \u0433\u043b\u0430\u0432\u043d\u043e\u0433\u043e \u044d\u0444\u0444\u0435\u043a\u0442\u0430 A. \u041e\u0436\u0438\u0434\u0430\u043d\u0438\u0435 \u2014 **\u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0435 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 A\u00d7B**: \u043f\u043e\u0434 random (A3) \u0432\u044b\u0431\u043e\u0440 \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u2192 B-\u044d\u0444\u0444\u0435\u043a\u0442 \u2248 0 (\u0432\u0430\u0436\u043d\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0438\u0437\u043e\u043b\u044f\u0446\u0438\u0438 \u0444\u0430\u043a\u0442\u043e\u0440\u0430), \u043f\u043e\u0434 dynamic (A1) B-\u0440\u0430\u0437\u0431\u0440\u043e\u0441 > 0.\n- **H3 (\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c):** \u0432\u0430\u0440\u0438\u0430\u0446\u0438\u044f \u043f\u043e B \u043d\u0430 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0435 \u043a\u043e\u0440\u0440\u0435\u043b\u0438\u0440\u0443\u0435\u0442 \u0441 top-k hit-rate; hit-rate \u043c\u0435\u0434\u0438\u0438\u0440\u0443\u0435\u0442 \u044d\u0444\u0444\u0435\u043a\u0442 B \u043d\u0430 \u0441\u043a\u043e\u0440.\n- **H4 (\u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430 \u043f\u043e\u0442\u043e\u043b\u043a\u0430):** \u0434\u0430\u0436\u0435 \u043b\u0443\u0447\u0448\u0430\u044f \u0438\u0437\u0431\u0438\u0440\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u044f\u0447\u0435\u0439\u043a\u0430 (A1/B1) \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043d\u0438\u0436\u0435 full-attention-\u043f\u043e\u0442\u043e\u043b\u043a\u0430 \u043d\u0430 remote-\u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430\u0445 \u2014 \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u043c \u0440\u0430\u0437\u043c\u0435\u0440 \u0432\u0440\u043e\u0436\u0434\u0451\u043d\u043d\u043e\u0439 \u043f\u043e\u0442\u0435\u0440\u0438 \u0440\u0430\u0437\u0440\u0435\u0436\u0435\u043d\u043d\u043e\u0439 \u0430\u043f\u043f\u0440\u043e\u043a\u0441\u0438\u043c\u0430\u0446\u0438\u0438.\n\n## 2. \u0423\u0441\u043b\u043e\u0432\u0438\u044f (12 \u044f\u0447\u0435\u0435\u043a)\n\n**\u0411\u0430\u0437\u0430 (\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u0432\u043e \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445):** \u043e\u0434\u0438\u043d \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0439 backbone ~7\u20138B (LLaMA-3-8B-\u043a\u043b\u0430\u0441\u0441, \u0440\u0435\u0448\u0435\u043d\u0438\u0435 1); decoder-only, training-free \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441; \u0441\u0435\u0433\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044f \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430 \u043d\u0430 \u043a\u043e\u043d\u0442\u0438\u0433\u0443\u0430\u043b\u044c\u043d\u044b\u0435 \u044e\u043d\u0438\u0442\u044b \u0440\u0430\u0437\u043c\u0435\u0440\u0430 u=128 \u0442\u043e\u043a\u0435\u043d\u043e\u0432; \u0432\u0441\u0435\u0433\u0434\u0430 attends-\u043e\u043a\u043d\u043e W=1024 \u043d\u0435\u0434\u0430\u0432\u043d\u0438\u0445 \u0442\u043e\u043a\u0435\u043d\u043e\u0432; \u0447\u0438\u0441\u043b\u043e \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u044b\u0445 \u0438\u0437 \u043f\u0430\u043c\u044f\u0442\u0438 \u044e\u043d\u0438\u0442\u043e\u0432 k=4 \u2192 \u043e\u0431\u044a\u0451\u043c attend-\u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u044f\u0447\u0435\u0439\u043a\u0438 = W + k\u00b7u = 1024+512 = 1536 (\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e \u0434\u043b\u044f A1/A3/A2).\n\n**\u0424\u0430\u043a\u0442\u043e\u0440 A \u2014 lookup (3 \u0443\u0440\u043e\u0432\u043d\u044f \u0432 \u0441\u0435\u0442\u043a\u0435/\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430\u0445):**\n- **A1 DYNAMIC:** top-k \u044e\u043d\u0438\u0442\u043e\u0432 \u043f\u043e max attention-\u0441\u043a\u043e\u0440\u0443 \u0437\u0430\u043f\u0440\u043e\u0441\u0430 \u043a unit-\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f\u043c + \u043e\u043a\u043d\u043e W (\u0434\u0435\u0444\u043e\u043b\u0442\u043d\u044b\u0439 InfLLM-lookup).\n- **A2 WINDOW (\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441, \u0432\u043d\u0435 \u0441\u0435\u0442\u043a\u0438):** \u044e\u043d\u0438\u0442\u043e\u0432 \u043d\u0435\u0442; attends \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 1536 \u0442\u043e\u043a\u0435\u043d\u043e\u0432. \u041d\u0438\u0437 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u043d\u043e\u0439 \u0448\u043a\u0430\u043b\u044b.\n- **A3 RANDOM:** \u0442\u0435 \u0436\u0435 k \u044e\u043d\u0438\u0442\u043e\u0432, \u0442\u043e\u0442 \u0436\u0435 \u0431\u044e\u0434\u0436\u0435\u0442, \u043d\u043e \u0432\u044b\u0431\u043e\u0440 \u0440\u0430\u0432\u043d\u043e\u043c\u0435\u0440\u043d\u044b\u0439 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 (5 \u0441\u0438\u0434\u043e\u0432, \u0443\u0441\u0440\u0435\u0434\u043d\u0435\u043d\u0438\u0435 \u00b1SD). \u0418\u0437\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u00ab\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u0432\u044b\u0431\u043e\u0440\u0430\u00bb \u043e\u0442 \u00ab\u043d\u0430\u043b\u0438\u0447\u0438\u044f \u043f\u0430\u043c\u044f\u0442\u0438\u00bb.\n- **A4 FULL (\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441, \u0432\u043d\u0435 \u0441\u0435\u0442\u043a\u0438):** attention \u043f\u043e \u0432\u0441\u0435\u043c \u0442\u043e\u043a\u0435\u043d\u0430\u043c \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430, \u0431\u0435\u0437 \u0432\u044b\u0431\u043e\u0440\u0430. \u041f\u043e\u0442\u043e\u043b\u043e\u043a, **\u043d\u0435** budget-matched (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 3).\n\n**\u0424\u0430\u043a\u0442\u043e\u0440 B \u2014 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 (5 \u0443\u0440\u043e\u0432\u043d\u0435\u0439; \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043a A1 \u0438 A3, \u0432\u0430\u043a\u0443\u0443\u043c\u0435\u043d \u0434\u043b\u044f A2/A4):**\n- **B1 REP-TOKEN:** \u0432 \u043d\u0430\u0447\u0430\u043b\u043e \u0431\u043b\u043e\u043a\u0430 \u0432\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0432\u044b\u0434\u0435\u043b\u0435\u043d\u043d\u044b\u0439 \u0442\u043e\u043a\u0435\u043d-\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c; unit-\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 = hidden state \u0435\u0433\u043e \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0433\u043e \u0441\u043b\u043e\u044f (InfLLM-style).\n- **B2 MEAN:** \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 = mean-pool \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435-\u0441\u043b\u043e\u0439\u043d\u044b\u0445 hidden states \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0431\u043b\u043e\u043a\u0430.\n- **B3 MAX:** \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043d\u044b\u0439 max-pool \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0431\u043b\u043e\u043a\u0430.\n- **B4 FIRST-TOKEN:** \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 = hidden state \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0442\u043e\u043a\u0435\u043d\u0430 \u0431\u043b\u043e\u043a\u0430 (\u0431\u0435\u0437 \u0432\u0441\u0442\u0430\u0432\u043a\u0438 \u0434\u043e\u043f. \u0442\u043e\u043a\u0435\u043d\u0430).\n- **B5 ALL-TOKENS:** \u0431\u0435\u0437 \u0441\u0436\u0430\u0442\u0438\u044f \u0432 \u043e\u0434\u0438\u043d \u0432\u0435\u043a\u0442\u043e\u0440 \u2014 lookup-\u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043f\u043e \u0432\u0441\u0435\u043c \u043a\u043b\u044e\u0447\u0430\u043c \u044e\u043d\u0438\u0442\u0430 (unit-\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 = \u043f\u043e\u043b\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 KV \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0431\u043b\u043e\u043a\u0430).\n\n**\u0421\u0435\u0442\u043a\u0430 (\u0444\u0430\u043a\u0442\u043e\u0440\u043d\u044b\u0439 2\u00d75 = 10 \u044f\u0447\u0435\u0435\u043a):** A \u2208 {A1, A3} \u00d7 B \u2208 {B1\u2026B5}, \u0432\u0441\u0435 \u043d\u0430 \u043e\u0434\u043d\u0438\u0445 \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u0430\u0445 (paired, within-subject). **\u041f\u043b\u044e\u0441 2 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430** A2, A4 (\u0432\u043d\u0435 \u0441\u0435\u0442\u043a\u0438, \u0442.\u043a. \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f) \u2192 \u0438\u0442\u043e\u0433\u043e 12 \u0443\u0441\u043b\u043e\u0432\u0438\u0439.\n\n*\u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 5 B-\u044f\u0447\u0435\u0435\u043a \u043f\u043e\u0434 A3 (\u0433\u0434\u0435 B \u0432\u0430\u043a\u0443\u0443\u043c\u0435\u043d):* \u044d\u0442\u043e **\u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c** \u2014 \u043e\u043d\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0434\u0430\u0442\u044c \u043f\u043e\u0447\u0442\u0438 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0435 \u0441\u043a\u043e\u0440\u044b \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 seed-\u0440\u0430\u0437\u0431\u0440\u043e\u0441\u0430. \u042d\u0442\u043e \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u043e\u043d\u043d\u043e\u0439 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u0438 (B \u043d\u0435 \u043f\u0440\u043e\u0442\u0435\u043a\u0430\u0435\u0442 \u0432 decode-attention) \u0438 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u0438\u0437\u043e\u043b\u044f\u0446\u0438\u0438 \u0444\u0430\u043a\u0442\u043e\u0440\u0430.\n\n*\u041f\u043e\u0447\u0435\u043c\u0443 \u0444\u0430\u043a\u0442\u043e\u0440\u043d\u044b\u0439 2\u00d7K:* \u0432\u043e\u043f\u0440\u043e\u0441 = \u0434\u0432\u0430 \u0433\u043b\u0430\u0432\u043d\u044b\u0445 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 + \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435; \u0441\u0435\u0442\u043a\u0430 \u043c\u0430\u043b\u0430 (\u043f\u043e\u043b\u043d\u044b\u0439 \u0444\u0430\u043a\u0442\u043e\u0440\u043d\u044b\u0439 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c, \u0434\u0440\u043e\u0431\u043d\u044b\u0439 \u043d\u0435 \u043d\u0443\u0436\u0435\u043d); B \u043f\u043e\u0447\u0442\u0438 \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e-\u043d\u0435\u0439\u0442\u0440\u0430\u043b\u0435\u043d \u0434\u043b\u044f \u0438\u0442\u043e\u0433\u043e\u0432\u043e\u0433\u043e \u0441\u043a\u043e\u0440\u0430 (\u043c\u0435\u043d\u044f\u0435\u0442 \u043b\u0438\u0448\u044c \u0434\u0435\u0448\u0451\u0432\u044b\u0439 lookup-\u044d\u0442\u0430\u043f, \u043d\u0435 \u0447\u0438\u0441\u043b\u043e attend-\u0442\u043e\u043a\u0435\u043d\u043e\u0432) \u2014 \u0438\u0434\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u0430\u044f \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f: \u043c\u0435\u0440\u044f\u0435\u043c \u0446\u0435\u043d\u0443 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u00ab\u0441\u0436\u0430\u0442\u0438\u044f\u00bb, \u0430 \u043d\u0435 \u0446\u0435\u043d\u0443 \u0444\u043b\u043e\u043f\u043e\u0432.\n\n## 3. \u0417\u0430\u0434\u0430\u0447\u0438 \u0438 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435\n\n**\u042f\u0434\u0440\u043e (\u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430 \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c ground-truth unit):**\n1. **Passkey/needle-in-a-haystack:** \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u044e\u0449\u0438\u0439\u0441\u044f filler + \u0438\u0433\u043b\u0430-passkey \u0441 \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u043c \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435\u043c. \u0421\u0435\u0442\u043a\u0430 \u0434\u043b\u0438\u043d L \u2208 {4K,8K,16K,32K,64K,128K} \u00d7 \u0433\u043b\u0443\u0431\u0438\u043d\u044b d \u2208 {early=10%, mid=50%, late=90%} \u00d7 20 \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u043e\u0432 \u043d\u0430 \u044f\u0447\u0435\u0439\u043a\u0443 (\u0440\u0430\u0437\u043d\u044b\u0435 filler/\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f/\u0444\u043e\u0440\u043c\u0430\u0442\u044b \u0438\u0433\u043b\u044b; \u043f\u043b\u044e\u0441 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e multi-needle \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u043e\u0432 \u043a\u0430\u043a robustness). \u0418\u0442\u043e\u0433: 6\u00d73\u00d720 = 360 \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u043e\u0432.\n2. **\u221eBench-\u0441\u0442\u0438\u043b\u044c \u0437\u0430\u0434\u0430\u0447\u0438 \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c \u043c\u0435\u0441\u0442\u043e\u043c \u0444\u0430\u043a\u0442\u0430:** \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 multi-retrieval QA, \u0433\u0434\u0435 \u043e\u0442\u0432\u0435\u0442-\u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043b\u0435\u0436\u0438\u0442 \u0432 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0439 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 (early/mid/late); \u0442\u0430 \u0436\u0435 \u0441\u0435\u0442\u043a\u0430 \u0434\u043b\u0438\u043d; \u043f\u043e\u0437\u0438\u0446\u0438\u044f \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430 \u21d2 \u0442\u043e\u0447\u043d\u044b\u0439 \u043f\u043e\u0434\u0441\u0447\u0451\u0442 hit-rate. 360 \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u043e\u0432.\n\n**\u0412\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 (\u0432\u043d\u0435\u0448\u043d\u044f\u044f \u0432\u0430\u043b\u0438\u0434\u043d\u043e\u0441\u0442\u044c, LongBench-\u043a\u043b\u0430\u0441\u0441, \u2248120 \u043f\u0443\u043d\u043a\u0442\u043e\u0432):**\n- single-doc QA (NarrativeQA, Qasper), multi-doc QA (MultiFieldQA, HotpotQA), summarization (ROUGE, \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e), few-shot (TREC-\u0441\u0442\u0438\u043b\u044c). \u041e\u0442\u0447\u0451\u0442 \u0441\u0442\u0440\u043e\u0433\u043e \u043f\u043e \u043f\u043e\u0434\u0437\u0430\u0434\u0430\u0447\u0430\u043c, \u0431\u0435\u0437 \u0441\u043b\u0435\u043f\u043e\u0439 \u0430\u0433\u0440\u0435\u0433\u0430\u0446\u0438\u0438. \u0414\u043b\u044f \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0438\u0438 \u00ab\u043f\u0430\u043c\u044f\u0442\u044c \u2194 \u0432\u043e\u043f\u0440\u043e\u0441\u00bb \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0435 \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u044b \u043c\u043e\u0436\u043d\u043e \u043e\u0431\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0442\u044c filler-\u0442\u0435\u043a\u0441\u0442\u043e\u043c, \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044f \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435.\n\n**\u041e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e (sanity/secondary):** perplexity \u043d\u0430 \u0434\u043b\u0438\u043d\u043d\u044b\u0445 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0445 (PG19-\u043a\u043b\u0430\u0441\u0441) \u043f\u043e \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043d\u043e\u0439 \u043f\u043e\u0437\u0438\u0446\u0438\u0438; \u043f\u0435\u0440\u0435\u0433\u043e\u043d \u0441\u0435\u0442\u043a\u0438 \u043d\u0430 \u043c\u0430\u043b\u043e\u043c backbone (1\u20133B) \u2014 \u043e\u0431\u043e\u0431\u0449\u0435\u043d\u0438\u0435 (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 1: \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e).\n\n**DV:**\n- *\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0435:* exact/normalized-match accuracy \u043d\u0430 passkey \u0438 \u221e-\u0441\u0442\u0438\u043b\u044c \u043f\u043e (\u0434\u043b\u0438\u043d\u0430\u00d7\u0433\u043b\u0443\u0431\u0438\u043d\u0430); NM/ROUGE \u043d\u0430 LongBench-\u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435 \u2014 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 4).\n- *\u0412\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0435:* LLM-judge (\u043e\u0434\u043d\u0430 \u0438 \u0442\u0430 \u0436\u0435 judge-\u043c\u043e\u0434\u0435\u043b\u044c + \u0444\u0438\u043a\u0441. \u043f\u0440\u043e\u043c\u043f\u0442 + \u0444\u0438\u043a\u0441. decoding \u043d\u0430 \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445, \u0442\u043e\u043b\u044c\u043a\u043e open-ended QA); top-k **unit hit-rate**; \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c, FLOPs, \u0440\u0430\u0437\u043c\u0435\u0440 KV-\u0431\u0443\u0444\u0435\u0440\u0430.\n\n## 4. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\n\n- \u041e\u0434\u0438\u043d backbone \u043d\u0430 \u0432\u0441\u0435 12 \u044f\u0447\u0435\u0435\u043a; \u0444\u0438\u043a\u0441. u, k, W \u0438 \u0441\u0435\u0433\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044f; \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0448\u0430\u0431\u043b\u043e\u043d\u044b/\u043f\u0440\u043e\u043c\u043f\u0442\u044b/\u043f\u0440\u0438\u043c\u0435\u0440\u044b/\u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u043e\u0432 (paired: \u043e\u0434\u0438\u043d \u0438\u043d\u0441\u0442\u0430\u043d\u0441 \u043f\u0440\u043e\u0445\u043e\u0434\u044f\u0442 \u0432\u0441\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f).\n- \u0424\u0438\u043a\u0441. decoding: greedy (temp=0) \u043a\u0430\u043a \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439; \u0447\u0430\u0441\u0442\u044c \u044f\u0447\u0435\u0435\u043a \u0441 sampling + \u0441\u0438\u0434\u0430\u043c\u0438 \u0434\u043b\u044f \u043e\u0446\u0435\u043d\u043a\u0438 \u0434\u0438\u0441\u043f\u0435\u0440\u0441\u0438\u0438; \u0444\u0438\u043a\u0441. max new tokens.\n- \u0421\u0438\u0434\u044b \u0434\u043b\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u043e\u0432 \u0438 \u0434\u043b\u044f A3 (5 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0445 \u0441\u0438\u0434\u043e\u0432, \u0441\u0440\u0435\u0434\u043d\u0435\u0435\u00b1SD).\n- \u0415\u0434\u0438\u043d\u044b\u0439 eval harness: \u043e\u0434\u0438\u043d \u043a\u043e\u0434 \u0441\u043a\u043e\u0440\u0435\u043d\u0438\u044f, \u043e\u0434\u043d\u0430 \u0441\u0445\u0435\u043c\u0430 \u043b\u043e\u0433\u043e\u0432; **\u0441\u043b\u0435\u043f\u043e\u0435 \u0441\u043a\u043e\u0440\u0435\u043d\u0438\u0435** (\u0441\u043a\u043e\u0440\u0438\u043d\u0433-\u0441\u043a\u0440\u0438\u043f\u0442 \u043d\u0435 \u0437\u043d\u0430\u0435\u0442 \u0438\u043c\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u044f).\n- \u0411\u044e\u0434\u0436\u0435\u0442-\u043c\u0430\u0442\u0447\u0438\u043d\u0433 A1/A3/A2 \u043f\u043e \u0447\u0438\u0441\u043b\u0443 attend-\u0442\u043e\u043a\u0435\u043d\u043e\u0432 (1536); A4 \u2014 \u0432\u043d\u0435 \u043c\u0430\u0442\u0447\u0438\u043d\u0433\u0430 (\u043f\u043e\u0442\u043e\u043b\u043e\u043a).\n- \u0421\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f \u0436\u0435\u043b\u0435\u0437\u0430/\u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0435\u043a; judge (\u0435\u0441\u043b\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f) \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0435\u0434\u0438\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043d\u043e.\n\n## 5. \u041a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u044b \u0438 \u0443\u0447\u0451\u0442\n\n- **Recent bias / \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c:** \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0441\u0438\u0433\u043d\u0430\u043b \u2014 early/mid-\u0438\u0433\u043b\u044b; late-\u0438\u0433\u043b\u044b \u043a\u0430\u043a control (\u043e\u043a\u043d\u043e \u0438\u0445 \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442); \u043e\u0442\u0447\u0451\u0442 \u043f\u043e \u0433\u043b\u0443\u0431\u0438\u043d\u0430\u043c \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e.\n- **\u0420\u0430\u0437\u043c\u0435\u0440 \u044e\u043d\u0438\u0442\u0430 \u00d7 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435:** \u0444\u0438\u043a\u0441. u=128 \u0432 \u0441\u0435\u0442\u043a\u0435; \u043d\u0435\u0431\u043e\u043b\u044c\u0448\u043e\u0439 robustness-\u043f\u0440\u043e\u0433\u043e\u043d u\u2208{64,256} \u043d\u0430 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435 (A1-\u0441\u0435\u0442\u043a\u0430, passkey 32K).\n- **\u0427\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043a k:** \u0444\u0438\u043a\u0441. k=4 \u0432 \u0441\u0435\u0442\u043a\u0435; \u043f\u043e\u0434\u043f\u0440\u043e\u0433\u043e\u043d k\u2208{2,4,8} \u043d\u0430 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435.\n- **A3 \u0438 \u0432\u044b\u0431\u043e\u0440 k:** random-\u0432\u044b\u0431\u043e\u0440 \u0438\u0437 k \u044e\u043d\u0438\u0442\u043e\u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 k \u0438\u043d\u0430\u0447\u0435, \u0447\u0435\u043c dynamic \u2192 \u0434\u0435\u0440\u0436\u0438\u043c k/u \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u043c\u0438, seed-\u0443\u0441\u0440\u0435\u0434\u043d\u0435\u043d\u0438\u0435.\n- **\u0413\u0435\u0442\u0435\u0440\u043e\u0433\u0435\u043d\u043d\u043e\u0441\u0442\u044c LongBench:** per-subtask + \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0430\u0433\u0440\u0435\u0433\u0430\u0446\u0438\u044f; \u043d\u0435 \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0442\u044c \u0432\u0441\u043b\u0435\u043f\u0443\u044e.\n- **\u0424\u043e\u0440\u043c\u0430\u0442\u043d\u044b\u0435 \u0448\u043e\u0440\u0442\u043a\u0430\u0442\u044b passkey:** \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0444\u043e\u0440\u043c\u0430\u0442\u043e\u0432/\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439; multi-needle.\n- **\u041a\u043e\u043d\u0442\u0430\u043c\u0438\u043d\u0430\u0446\u0438\u044f \u0437\u0430\u0434\u0430\u0447:** \u043f\u0440\u0435\u0434\u043f\u043e\u0447\u0438\u0442\u0430\u0435\u043c hold-out/\u043d\u0435\u0434\u0430\u0432\u043d\u0438\u0435 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430; \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u044b\u0439 \u0440\u0438\u0441\u043a \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f.\n- **\u0418\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u044f arms** (masking, \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0441\u0442\u0435\u043a\u0430 \u0442\u043e\u043a\u0435\u043d\u043e\u0432, KV): \u043e\u0431\u0449\u0438\u0439 \u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441 \u0434\u0435\u043a\u043e\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f, \u044e\u043d\u0438\u0442-\u0442\u0435\u0441\u0442\u044b \u043c\u0430\u0441\u043e\u043a \u0438 \u0447\u0438\u0441\u043b\u0430 attend-\u0442\u043e\u043a\u0435\u043d\u043e\u0432; 5 B-\u044f\u0447\u0435\u0435\u043a \u043f\u043e\u0434 A3 \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438 \u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438.\n- **\u0410\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f \u0431\u044e\u0434\u0436\u0435\u0442\u0430 (A4/A2):** \u0434\u0432\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u044b \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442 \u2014 \u00ab\u0440\u0430\u0432\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442\u00bb (\u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f) \u0438 \u00ab\u043f\u043e\u0442\u043e\u043b\u043e\u043a \u0431\u0435\u0437 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f\u00bb (\u0432\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f).\n- **\u041f\u043e\u0437\u0438\u0446\u0438\u043e\u043d\u043d\u044b\u0435/\u043f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0435 \u0441\u043c\u0435\u0449\u0435\u043d\u0438\u044f backbone \u043d\u0430 \u0431\u043e\u043b\u044c\u0448\u0438\u0445 \u0434\u043b\u0438\u043d\u0430\u0445:** \u043e\u0442\u0447\u0451\u0442 \u043f\u043e \u0434\u043b\u0438\u043d\u0430\u043c; floor-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043f\u0430\u0441\u0441\u0438\u0432\u043d\u043e\u0433\u043e \u043e\u043a\u043d\u0430 backbone.\n\n## 6. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430\n\n- \u0415\u0434\u0438\u043d\u0438\u0446\u0430 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u2014 \u0438\u043d\u0441\u0442\u0430\u043d\u0441; \u044f\u0447\u0435\u0439\u043a\u0438 \u0441\u043f\u0430\u0440\u0435\u043d\u044b \u043d\u0430 \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u0430\u0445.\n- **\u0421\u0435\u0442\u043a\u0430 2\u00d75:** mixed-effects \u043c\u043e\u0434\u0435\u043b\u044c `score ~ A + B + A:B + (1|instance) + (1|task_cell)` \u043f\u043e \u0441\u0442\u0440\u0430\u0442\u0430\u043c (\u0434\u043b\u0438\u043d\u0430\u00d7\u0433\u043b\u0443\u0431\u0438\u043d\u0430) \u0438 \u0432 \u0430\u0433\u0440\u0435\u0433\u0430\u0442\u0435; \u0433\u043b\u0430\u0432\u043d\u044b\u0435 \u044d\u0444\u0444\u0435\u043a\u0442\u044b, \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435; **partial \u03b7\u00b2** \u0438 \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u0435 \u0394 (lookup-\u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c = A1\u2212A3 \u043f\u0440\u0438 \u043a\u0430\u0436\u0434\u043e\u043c B; \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435-\u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c = \u0440\u0430\u0437\u043c\u0430\u0445 B \u043f\u043e\u0434 A1); \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u044d\u0444\u0444\u0435\u043a\u0442\u044b.\n- **\u0420\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u044b:** \u043f\u0430\u0440\u043d\u044b\u0435 \u0442\u0435\u0441\u0442\u044b \u043a\u0430\u0436\u0434\u043e\u0439 \u044f\u0447\u0435\u0439\u043a\u0438 \u043f\u0440\u043e\u0442\u0438\u0432 A2 (\u0432\u043d\u0438\u0437) \u0438 A4 (\u0432\u0432\u0435\u0440\u0445) \u2192 \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u0432\u0441\u0435\u0445 10 \u044f\u0447\u0435\u0435\u043a \u043d\u0430 \u0448\u043a\u0430\u043b\u0435 \u00ab\u043e\u043a\u043d\u043e \u2194 \u043f\u043e\u0442\u043e\u043b\u043e\u043a\u00bb; \u00ab\u0434\u043e\u043b\u044f \u0437\u0430\u043a\u0440\u044b\u0442\u043e\u0433\u043e gap \u0434\u043e \u043f\u043e\u0442\u043e\u043b\u043a\u0430\u00bb \u043d\u0430 remote-\u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430\u0445 \u043a\u0430\u043a \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u043c\u0435\u0440\u0430 \u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438.\n- **\u041c\u0435\u0445\u0430\u043d\u0438\u0437\u043c:** hit-rate (\u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430 \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c ground-truth unit) \u043a\u0430\u043a \u043c\u0435\u0434\u0438\u0430\u0442\u043e\u0440 \u2014 bootstrap-\u043c\u0435\u0434\u0438\u0430\u0446\u0438\u044f \u043b\u0438\u0431\u043e \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f \u0441\u043a\u043e\u0440\u0430 \u043d\u0430 hit-rate \u0441 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u043c \u0443\u0441\u043b\u043e\u0432\u0438\u044f; \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 B-\u0440\u0430\u0437\u043d\u0438\u0446\u044b hit-rate \u0441 B-\u0440\u0430\u0437\u043d\u0438\u0446\u0435\u0439 \u0441\u043a\u043e\u0440\u0430.\n- **Robustness:** \u043f\u043e \u0434\u043b\u0438\u043d\u0435 (\u0440\u0430\u0441\u0442\u0451\u0442 \u043b\u0438 \u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c lookup \u0441 L \u21d2 \u00ab\u043f\u043e\u0442\u0440\u0435\u0431\u043d\u043e\u0441\u0442\u044c \u0432 \u0443\u0434\u0430\u043b\u0451\u043d\u043d\u043e\u0439 \u043f\u0430\u043c\u044f\u0442\u0438\u00bb); \u043f\u043e \u0433\u043b\u0443\u0431\u0438\u043d\u0435; \u043f\u043e k/u-\u043f\u043e\u0434\u043f\u0440\u043e\u0433\u043e\u043d\u0430\u043c; \u043f\u043e \u0441\u0438\u0434\u0430\u043c.\n- **\u041c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c:** \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0432 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0439 \u0441 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430\u043c\u0438 (Holm-Bonferroni), CI \u0432\u0435\u0437\u0434\u0435.\n- **Gate (design-only):** \u043f\u0435\u0440\u0435\u0434 \u043f\u043e\u043b\u043d\u043e\u0439 \u0441\u0435\u0442\u043a\u043e\u0439 \u2014 smoke-\u043f\u0440\u043e\u0433\u043e\u043d (A1/B1, A2, A4 \u043d\u0430 passkey 16K, 1\u20132 \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u0430) \u0434\u043b\u044f \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u0438 harness \u0438 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e\u0433\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u0432.\n\n## 7. \u0412\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u044c (\u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441-only, \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0432\u0435\u043b\u0438\u0447\u0438\u043d)\n\n\u041f\u043e\u043b\u043d\u044b\u0439 \u0441\u0435\u0442 = 12 \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u00d7 (360 passkey + 360 \u221e\u0441\u0442\u0438\u043b\u044c + ~120 LongBench + ~20 PPL) \u2248 **~10\u201311 \u0442\u044b\u0441. \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0435\u0439**, \u043f\u043e ~200\u2013300 \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u043c\u044b\u0445 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u043d\u0430 \u043f\u0443\u043d\u043a\u0442. \u0412 \u0438\u0437\u0431\u0438\u0440\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 arms \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f per-token \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441\u043e\u043c backbone (\u2248\u00ab\u043e\u0431\u044b\u0447\u043d\u0430\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f ~250 \u0442\u043e\u043a\u0435\u043d\u043e\u0432\u00bb), \u0442.\u043a. \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043e 1536 attend-\u0442\u043e\u043a\u0435\u043d\u0430\u043c\u0438; 128K-\u044f\u0447\u0435\u0439\u043a\u0438 \u043d\u0435 \u0432\u0437\u0434\u0443\u0432\u0430\u044e\u0442 \u0444\u043b\u043e\u043f\u044b (\u0442\u043e\u043b\u044c\u043a\u043e lookup \u043f\u043e ~\u043e\u0434\u043d\u043e\u043c\u0443 \u044e\u043d\u0438\u0442\u0443 \u043d\u0430 \u0442\u043e\u043a\u0435\u043d), \u043d\u043e \u0432\u0437\u0434\u0443\u0432\u0430\u044e\u0442 **KV-\u043f\u0430\u043c\u044f\u0442\u044c**: KV \u043d\u0430 128K \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0434\u043b\u044f 7\u20138B fp16 \u2248 100+ \u0413\u0411 \u2192 \u043d\u0430 \u0434\u043b\u0438\u043d\u0430\u0445 \u226564\u2013128K \u043d\u0443\u0436\u043d\u044b fp8-KV / CPU-offload / \u0447\u0430\u043d\u043a\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435, \u043b\u0438\u0431\u043e \u043f\u043e\u0442\u043e\u043b\u043e\u043a \u0434\u043b\u0438\u043d. **A4 (full attention)** \u043d\u0430 \u0434\u043b\u0438\u043d\u043d\u044b\u0445 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430\u0445 \u2014 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0434\u043e\u0440\u043e\u0433\u0430\u044f \u044f\u0447\u0435\u0439\u043a\u0430 (O(len\u00b2) attention \u0434\u043e 128K): cap A4 \u043d\u0430 \u226432K \u0441 \u0441\u0443\u0431\u0441\u044d\u043c\u043f\u043b\u0438\u043d\u0433\u043e\u043c \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u043e\u0432 \u043d\u0430 \u0431\u00f3\u043b\u044c\u0448\u0438\u0445 \u0434\u043b\u0438\u043d\u0430\u0445 (A4 \u043d\u0430 128K \u2014 \u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e). \u0412 CPU-only (224 \u044f\u0434\u0440\u0430) \u043f\u0440\u043e\u0433\u043e\u043d 7\u20138B \u043d\u0430 128K \u2014 \u0435\u0434\u0438\u043d\u0438\u0446\u044b\u2013\u0434\u0435\u0441\u044f\u0442\u043a\u0438 \u043c\u0438\u043d\u0443\u0442 \u043d\u0430 \u043f\u0443\u043d\u043a\u0442 (\u0432 GPU-\u0441\u0440\u0435\u0434\u0435 \u2014 \u0441\u0435\u043a\u0443\u043d\u0434\u044b\u2013\u043c\u0438\u043d\u0443\u0442\u044b); \u043f\u0440\u0438 \u0436\u0451\u0441\u0442\u043a\u043e\u043c \u0431\u044e\u0434\u0436\u0435\u0442\u0435 \u0434\u0435\u0440\u0436\u0430\u0442\u044c 128K-\u044f\u0447\u0435\u0439\u043a\u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0438\u0437\u0431\u0438\u0440\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 arms \u0438 \u043c\u0430\u043b\u043e\u0433\u043e backbone-\u043f\u0440\u043e\u0433\u043e\u043d\u0430. \u041f\u043e\u0440\u044f\u0434\u043e\u043a \u0432\u0435\u043b\u0438\u0447\u0438\u043d \u0438 \u043f\u043e\u0440\u043e\u0433 gate-\u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430.\n\n## 8. Assumptions (\u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e)\n\n1. Design-only; \u043f\u0440\u043e\u0433\u043e\u043d \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f, \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043d\u0435 \u0432\u044b\u0434\u0443\u043c\u044b\u0432\u0430\u044e\u0442\u0441\u044f (\u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u0434\u0430\u0447\u0438).\n2. \u041e\u0434\u0438\u043d backbone ~7\u20138B \u043d\u0430 \u0432\u0441\u0435\u0445 12 \u044f\u0447\u0435\u0439\u043a\u0430\u0445; \u043c\u0430\u043b\u044b\u0439 backbone (1\u20133B) \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043e\u043d (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 1).\n3. \u042f\u0434\u0440\u043e \u0432\u044b\u0432\u043e\u0434\u0430 \u2014 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430 \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c ground-truth unit; LongBench-\u043a\u043b\u0430\u0441\u0441 \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439; \u043f\u043e\u043b\u043d\u044b\u0439 LongBench \u043d\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d; \u043e\u0442\u0447\u0451\u0442 \u043f\u043e \u043f\u043e\u0434\u0437\u0430\u0434\u0430\u0447\u0430\u043c (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 2).\n4. A4 = \u043f\u043e\u0442\u043e\u043b\u043e\u043a (\u043d\u0435 budget-matched), A2 = \u043d\u0438\u0437 \u0448\u043a\u0430\u043b\u044b (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 3).\n5. \u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 (exact/NM, ROUGE); LLM-judge \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439, \u0444\u0438\u043a\u0441. judge-\u043c\u043e\u0434\u0435\u043b\u044c+\u043f\u0440\u043e\u043c\u043f\u0442 (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 4).\n6. Mixed-effects/paired \u0430\u043d\u0430\u043b\u0438\u0437, partial \u03b7\u00b2 + \u0394, hit-rate-\u043c\u0435\u0434\u0438\u0430\u0446\u0438\u044f (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 5).\n7. \u0410\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u043d\u044b\u0435 \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u044b InfLLM (u=128, k=4, W=1024, rep-token \u043a\u0430\u043a B1, top-k \u043f\u043e lookup-\u0432\u043d\u0438\u043c\u0430\u043d\u0438\u044e, training-free, \u0432\u0441\u0435\u0433\u0434\u0430 \u043e\u043a\u043d\u043e W) \u2014 \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u044b \u0434\u0438\u0437\u0430\u0439\u043d\u0430, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0432\u043e \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445; \u0442\u043e\u0447\u043d\u044b\u0435 \u0434\u0435\u0444\u043e\u043b\u0442\u044b \u0441\u0442\u0430\u0442\u044c\u0438 \u0441\u0432\u0435\u0440\u044f\u044e\u0442\u0441\u044f \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u0435 \u043a \u043a\u043e\u0434\u0443/\u0441\u0435\u0442\u0438 (\u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e: \u0432 /workspace \u043a\u043e\u0434\u0430 \u043d\u0435\u0442, \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430).\n8. B \u0432\u043b\u0438\u044f\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0432\u044b\u0431\u043e\u0440 \u044e\u043d\u0438\u0442\u043e\u0432, \u043d\u0435 \u043d\u0430 decode-attention (\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u043c A3\u00d7B).\n\n## 9. Unresolved uncertainties\n\n1. \u0422\u043e\u0447\u043d\u044b\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0434\u0435\u0444\u043e\u043b\u0442\u0430 InfLLM (\u0440\u0430\u0437\u043c\u0435\u0440 \u044e\u043d\u0438\u0442\u0430, \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0440\u0435\u043f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0442\u043e\u043a\u0435\u043d\u0430, \u0441\u043b\u043e\u0438 \u0440\u0435\u043f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0446\u0438\u0438, \u0432\u0441\u0435\u0433\u0434\u0430 \u043b\u0438 \u043e\u043a\u043d\u043e) \u2014 \u0434\u0438\u0437\u0430\u0439\u043d \u043e\u0442 \u043d\u0438\u0445 \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 (\u0432\u0441\u0435 \u044f\u0447\u0435\u0439\u043a\u0438 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435), \u043d\u043e \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u0435 \u043a \u043a\u043e\u0434\u0443 \u0438\u0445 \u0441\u0442\u043e\u0438\u0442 \u043f\u0435\u0440\u0435\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u043a\u0430\u043a \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f.\n2. \u0421\u043c\u044b\u0441\u043b \u00abunit representations\u00bb \u0432 \u0438\u0441\u0445\u043e\u0434\u043d\u043e\u043c \u0432\u043e\u043f\u0440\u043e\u0441\u0435 \u2014 \u0434\u0438\u0437\u0430\u0439\u043d \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043e\u0431\u0430 \u043a\u043e\u043d\u0446\u0430 \u0441\u043f\u0435\u043a\u0442\u0440\u0430 (\u0441\u0436\u0430\u0442\u0438\u0435\u2192\u043f\u043e\u043b\u043d\u044b\u0439 \u043a\u044d\u0448); \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044f \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u044d\u043c\u043f\u0438\u0440\u0438\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u043c.\n3. \u0414\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c/\u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 LongBench-\u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432 \u0438 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0439 7\u20138B \u043c\u043e\u0434\u0435\u043b\u0438 \u0432 \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u0441\u0440\u0435\u0434\u0435.\n4. \u0411\u044e\u0434\u0436\u0435\u0442: 128K-\u044f\u0447\u0435\u0439\u043a\u0438 \u0438 A4 \u043d\u0430 \u0434\u043b\u0438\u043d\u043d\u044b\u0445 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430\u0445 \u2014 \u0441\u0430\u043c\u0430\u044f \u0434\u043e\u0440\u043e\u0433\u0430\u044f \u0447\u0430\u0441\u0442\u044c; \u0442\u043e\u0447\u043d\u043e\u0435 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 (cap \u0434\u043b\u0438\u043d, \u0440\u0430\u0437\u043c\u0435\u0440 backbone, GPU/CPU) \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f gate-\u043f\u0440\u043e\u0433\u043e\u043d\u043e\u043c.\n5. \u041f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0435 B1-\u0434\u0435\u0444\u043e\u043b\u0442\u0430 \u0441\u043e \u00ab\u0441\u0442\u0430\u0440\u0442\u043e\u0432\u044b\u043c\u00bb \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435\u043c backbone \u043f\u0440\u0438 \u0432\u0441\u0442\u0430\u0432\u043a\u0435 \u0440\u0435\u043f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0442\u043e\u043a\u0435\u043d\u0430 \u0432 \u0431\u043b\u043e\u043a\u0438 \u2014 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u044d\u0444\u0444\u0435\u043a\u0442, \u043d\u043e \u043e\u043d \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432 \u0432\u043e \u0432\u0441\u0435\u0445 arms \u0438 \u043d\u0435 \u0438\u0441\u043a\u0430\u0436\u0430\u0435\u0442 \u0441\u0440\u0430\u0432\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0432\u044b\u0432\u043e\u0434\u044b.", "evidence": "\u0418\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f: /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json; track.md/InfLLM \u043a\u043e\u0434\u0430 \u043d\u0435\u0442 \u043d\u0438\u0433\u0434\u0435 \u0432 \u0434\u0435\u0440\u0435\u0432\u0435 (find). task.json: \"Design-only task; repositories and compute are not required.\" \u0421\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430, GPU \u043d\u0435\u0442, 224 CPU, \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0439 python. \u041a\u043e\u0434 InfLLM \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u2014 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a assumption (\u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e). \u041f\u043b\u0430\u043d \u043e\u0434\u043e\u0431\u0440\u0435\u043d \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u043c \u0441 \u0440\u0435\u0448\u0435\u043d\u0438\u044f\u043c\u0438 (1)\u2013(5): \u043e\u0434\u0438\u043d backbone 7\u20138B, \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430-\u044f\u0434\u0440\u043e + LongBench-\u0432\u0442\u043e\u0440\u0438\u0447\u043d\u043e, A4-\u043f\u043e\u0442\u043e\u043b\u043e\u043a \u0438 A2-\u043d\u0438\u0437, \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 + \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 judge, mixed-effects/paired + partial \u03b7\u00b2 + hit-rate-\u043c\u0435\u0434\u0438\u0430\u0446\u0438\u044f.", "assumptions": ["Design-only; \u043f\u0440\u043e\u0433\u043e\u043d \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f, \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043d\u0435 \u0432\u044b\u0434\u0443\u043c\u044b\u0432\u0430\u044e\u0442\u0441\u044f", "\u041e\u0434\u0438\u043d backbone ~7\u20138B \u043a\u043b\u0430\u0441\u0441\u0430 LLaMA-3-8B \u043d\u0430 \u0432\u0441\u0435\u0445 12 \u044f\u0447\u0435\u0439\u043a\u0430\u0445; \u043c\u0430\u043b\u044b\u0439 backbone 1\u20133B \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043e\u043d (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 1)", "\u042f\u0434\u0440\u043e \u0432\u044b\u0432\u043e\u0434\u0430 \u2014 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430 \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c ground-truth unit (passkey/needle + \u221eBench-\u0441\u0442\u0438\u043b\u044c); LongBench-\u043a\u043b\u0430\u0441\u0441 \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440, \u043e\u0442\u0447\u0451\u0442 \u043f\u043e \u043f\u043e\u0434\u0437\u0430\u0434\u0430\u0447\u0430\u043c (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 2)", "A4 full attention \u2014 \u043f\u043e\u0442\u043e\u043b\u043e\u043a (\u043d\u0435 budget-matched), A2 \u043e\u043a\u043d\u043e \u2014 \u043d\u0438\u0437 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u043d\u043e\u0439 \u0448\u043a\u0430\u043b\u044b (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 3)", "\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 (exact/NM, ROUGE); LLM-judge \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u044c\u044e \u0438 \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u043c (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 4)", "Mixed-effects/repeated-measures (\u0443\u0441\u043b\u043e\u0432\u0438\u044f \u2014 \u0444\u0438\u043a\u0441., \u0438\u043d\u0441\u0442\u0430\u043d\u0441\u044b \u2014 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0435), partial \u03b7\u00b2 + \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u0435 \u0394, \u043f\u0430\u0440\u043d\u044b\u0435 \u0442\u0435\u0441\u0442\u044b \u043f\u0440\u043e\u0442\u0438\u0432 A2/A4, hit-rate \u043a\u0430\u043a \u043c\u0435\u0434\u0438\u0430\u0442\u043e\u0440 (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 5)", "\u0410\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u043d\u044b\u0435 \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u044b InfLLM (u=128, k=4, W=1024, rep-token B1, top-k lookup, training-free, \u0432\u0441\u0435\u0433\u0434\u0430 \u043e\u043a\u043d\u043e) \u2014 \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u044b \u0434\u0438\u0437\u0430\u0439\u043d\u0430, \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0435 \u0432\u043e \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445; \u0434\u0435\u0444\u043e\u043b\u0442\u044b \u0441\u0442\u0430\u0442\u044c\u0438 \u0441\u0432\u0435\u0440\u044f\u044e\u0442\u0441\u044f \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u0435 \u043a \u043a\u043e\u0434\u0443/\u0441\u0435\u0442\u0438", "B (\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435) \u0432\u043b\u0438\u044f\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0432\u044b\u0431\u043e\u0440 \u044e\u043d\u0438\u0442\u043e\u0432, \u043d\u0435 \u043d\u0430 decode-attention \u2014 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u043c A3\u00d7B"], "uncertainties": ["\u0422\u043e\u0447\u043d\u044b\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0434\u0435\u0444\u043e\u043b\u0442\u0430 InfLLM (\u0440\u0430\u0437\u043c\u0435\u0440 \u044e\u043d\u0438\u0442\u0430, \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c rep-\u0442\u043e\u043a\u0435\u043d\u0430, \u0441\u043b\u043e\u0438 \u0440\u0435\u043f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0446\u0438\u0438, \u0432\u0441\u0435\u0433\u0434\u0430 \u043b\u0438 \u043e\u043a\u043d\u043e) \u2014 \u0434\u0438\u0437\u0430\u0439\u043d \u043e\u0442 \u043d\u0438\u0445 \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442, \u043d\u043e \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u0435 \u043a \u043a\u043e\u0434\u0443 \u0438\u0445 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u043a\u0430\u043a \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0435", "\u0421\u043c\u044b\u0441\u043b \u00abunit representations\u00bb \u0432 \u0438\u0441\u0445\u043e\u0434\u043d\u043e\u043c \u0432\u043e\u043f\u0440\u043e\u0441\u0435 \u2014 \u0434\u0438\u0437\u0430\u0439\u043d \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0441\u043f\u0435\u043a\